    'm4.zayiflama_duzeltmesi': { tex: '\\rho_{T_XT_Y}=\\rho_{XY}/\\sqrt{\\rho_{XX\'}\\rho_{YY\'}}', okuma: 'Zayıflama düzeltmesi.' },
    'm4.icc_a_1': { tex: '\\text{ICC}(A,1)=\\dfrac{\\hat\\sigma_p^2}{\\hat\\sigma_p^2+\\hat\\sigma_i^2+\\hat\\sigma^2_{pi,e}}', okuma: 'Mutlak uyum; ölçmeler arasındaki sabit kayma da hataya girer.' },
