    'm5.uc_standart_hata': { tex: '\\text{ölçme: }\\sigma_X\\sqrt{1-\\rho},\\ \\ \\text{kestirim: }\\sigma_X\\sqrt{\\rho(1-\\rho)},\\ \\ \\text{yordama: }\\sigma_X\\sqrt{1-\\rho^2}', okuma: 'Üç farklı standart hata üç farklı soruyu yanıtlar.' },
