    'm9.kanit_madde_varyanslari': { tex: '\\sum_i s_i^2=\\dfrac{KT_p+KT_{art}}{n-1}', okuma: '' },
    'm9.kanit_alpha_hoyt': { tex: '\\hat\\alpha=\\dfrac{k}{k-1}\\left(1-\\dfrac{KT_p+KT_{art}}{k\\,KT_p}\\right)=1-\\dfrac{KO_{art}}{KO_p}', okuma: 'Alfa ile Hoyt katsayısı cebirsel olarak aynıdır.' },
    'm9.beklenen_ko_kisi': { tex: '\\mathbb E(KO_p)=\\sigma^2_{pi,e}+n_i\\sigma_p^2', okuma: '' },
