    'm9.bilesen_artik': { tex: '\\hat\\sigma^2_{pi,e}=KO_{art}', okuma: '' },
    'm9.erho2': { tex: '\\mathbb E\\rho^2=\\dfrac{' + H('t-kisi', '\\sigma_p^2') + '}{\\sigma_p^2+' + H('t-artik', '\\sigma^2_{pi,e}/n_i\'') + '}', okuma: 'G katsayısı: bağıl kararlar için güvenirlik.' },
    'm9.phi': { tex: '\\Phi=\\dfrac{' + H('t-kisi', '\\sigma_p^2') + '}{\\sigma_p^2+(' + H('t-madde', '\\sigma_i^2') + '+' + H('t-artik', '\\sigma^2_{pi,e}') + ')/n_i\'}', okuma: 'Mutlak kararlar için Phi katsayısı; madde güçlüğü farkları da hataya girer.' },
    'm9.phi_lambda': { tex: '\\Phi(\\lambda)=\\dfrac{\\sigma_p^2+(\\mu-\\lambda)^2}{\\sigma_p^2+(\\mu-\\lambda)^2+\\sigma^2_\\Delta}', okuma: 'Kesme puanına özgü Phi.' },
    'm9.phi_en_kucuk': { tex: '\\Phi=\\min_\\lambda\\Phi(\\lambda)=\\Phi(\\mu)', okuma: '' },
