    'm9.icc_c_1_tam': { tex: '\\mathbb E\\rho^2(n_i\'=1)=\\text{ICC}(C,1)=\\dfrac{KO_p-KO_{art}}{KO_p+(k-1)KO_{art}}', okuma: '' },
